const fs = require('fs');
const path = '/workspace/world.db';
const buf = fs.readFileSync(path);
// Read SQLite header to confirm it's a database
console.log('File header:', buf.slice(0, 16).toString('utf-8'));
console.log('File size:', buf.length);
