node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name);
  console.log('Columns:', info.map(c => c.name + ' (' + c.type + ')').join(', '));
  const count = db.prepare('SELECT COUNT(*) as cnt FROM ' + t.name).get();
  console.log('Row count:', count.cnt);
}
db.close();
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// First, find the contact with that phone number
const contact = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\").all();
console.log('Contact match:', JSON.stringify(contact, null, 2));

// Search messages by recipient phone number
const msgs = db.prepare(\"SELECT * FROM ts_messages WHERE recipient_phone_number = '+1-347-555-0169'\").all();
console.log('\nMessages to that number:', JSON.stringify(msgs, null, 2));

// Also search by content keyword
const allMsgs = db.prepare(\"SELECT * FROM ts_messages WHERE content LIKE '%apartment cleaning%'\").all();
console.log('\nMessages about apartment cleaning:', JSON.stringify(allMsgs, null, 2));

db.close();
"

